// The copy engine (src/facts.js) and the poster's bar geometry (src/poster.js), against the demo couple's
// real analysis (test/fixtures, regenerated by scripts/make-test-fixture.py).
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { makeContext, pickFacts, posterContent, receipts, duration } from "../src/facts.js";
import { barLayout } from "../src/poster.js";

const load = (name) => JSON.parse(readFileSync(new URL(`./fixtures/${name}`, import.meta.url), "utf8"));
const demo = load("demo-result.json");
const NAMES = { A: "Rohan", B: "Tara" };
const ctx = (data = demo, names = NAMES) => makeContext(data, names);
const clone = (x) => JSON.parse(JSON.stringify(x));
const withStat = (id, patch) => {
  const d = clone(demo);
  const s = d.stats.find((x) => x.id === id);
  if (patch === null) d.stats = d.stats.filter((x) => x.id !== id);
  else Object.assign(s.values, patch);
  return d;
};
/** Every string a person can read, from the reveal, the poster and the receipts. */
function allText(data = demo, names = NAMES) {
  const c = ctx(data, names);
  const facts = pickFacts(c);
  const p = posterContent(c);
  const r = receipts(c, facts);
  const out = [];
  for (const f of facts) out.push(f.kicker, f.big, f.line, f.how, ...(f.rows || []).flatMap((x) => [x.name, x.value]));
  out.push(...p.titles.map((t) => t.text), ...p.lines, ...p.credits, p.left, p.right);
  for (const s of r.sections) for (const i of s.items) out.push(i.label, i.text, i.how);
  out.push(...r.limits);
  return out.filter(Boolean);
}

test("the demo couple gets five facts, in story order", () => {
  const ids = pickFacts(ctx()).map((f) => f.id);
  assert.deepEqual(ids, ["first_message", "reply_median", "longest_monologue", "busiest_day", "first_ily"]);
});

test("the copy is specific: the real numbers, dates and quotes", () => {
  const [first, reply, run, busy, ily] = pickFacts(ctx());
  assert.equal(first.big, "“hi, is this Tara?”");
  assert.match(first.line, /47,381 more followed/);
  assert.deepEqual(reply.rows.map((r) => [r.name, r.value]), [["Rohan", "1 min 40 s"], ["Tara", "23 min"]]);
  assert.match(reply.how, /6,437 of Rohan’s replies and 6,378 of Tara’s/);
  assert.equal(run.big, "31 messages in a row");
  assert.match(run.line, /Tara has sent “hmm” 1,499 times in all/);
  assert.equal(busy.big, "1,204 messages");
  assert.match(busy.line, /six days without a word, until Rohan wrote first/);
  assert.match(busy.how, /last day of a 183-day streak/);
  assert.match(busy.how, /We can’t tell you why/);
  assert.equal(ily.kicker, "Day 47 · 19 February 2024");
  assert.equal(ily.line, "Slower to reply, first to say it. Rohan answered within a minute.");
});

test("nothing anyone reads carries a score, a weight, a decimal or a verdict label", () => {
  for (const data of [demo, load("demo-result-spicy.json")]) {
    for (const s of allText(data)) {
      assert.doesNotMatch(s, /\d\.\d/, `decimal in: ${s}`);
      assert.doesNotMatch(s, /\b(score|weight|archetype|meter)\b/i, `jargon in: ${s}`);
      assert.doesNotMatch(s, /THE (GHOST|DOUBLE TEXTER|PHILOSOPHER)|Nobody could/, `old copy in: ${s}`);
      assert.doesNotMatch(s, /undefined|NaN|null|\[object/, `broken template in: ${s}`);
    }
  }
});

test("the names you type are the names you read (quotes stay exactly as they were sent)", () => {
  const text = allText(demo, { A: "Chai", B: "Chitra" }).join("\n");
  const outsideQuotes = text.replace(/“[^”]*”/g, "");
  assert.doesNotMatch(outsideQuotes, /\bRohan\b|\bTara\b/);
  assert.match(text, /Chai/);
  assert.match(text, /Chitra said “I love you” first|Chitra said ‘I love you’ first/);
  assert.match(text, /“hi, is this Tara\?”/); // a real quote is not rewritten
});

test("the 'within a minute' line only appears when the answer really came within a minute", () => {
  const at = (dur) => pickFacts(ctx(withStat("first_ily", { dur }))).find((f) => f.id === "first_ily").line;
  assert.match(at(60), /within a minute/);
  assert.doesNotMatch(at(90), /within a minute/); // the old version said it up to two minutes
  assert.equal(at(90), "Slower to reply, first to say it.");
});

test("the twist is only told when the slower replier really said it first", () => {
  const ily = (patch) => pickFacts(ctx(withStat("first_ily", patch))).find((f) => f.id === "first_ily");
  assert.doesNotMatch(ily({ win: "A", W: "Rohan", L: "Tara" }).line, /Slower to reply/);
  const close = withStat("reply_median", { r: 1.4 }); // replies too close to call: no twist, and no reply card
  const facts = pickFacts(ctx(close));
  assert.notEqual(facts[1].id, "reply_median");
  assert.doesNotMatch(facts.find((f) => f.id === "first_ily").line, /Slower to reply/);
});

test("weak or missing stats hand over to their backups", () => {
  assert.equal(pickFacts(ctx(withStat("first_message", { q: null })))[0].id, "message_milestones");
  assert.equal(pickFacts(ctx(withStat("longest_monologue", { q: null })))[2].id, "ok_period");
  assert.equal(pickFacts(ctx(withStat("busiest_day", { x: 2 })))[3].id, "longest_streak");
  assert.equal(pickFacts(ctx(withStat("first_ily", null))).at(-1).id, "pet_name");
});

test("busiest day and silence are one story only when the dates really meet", () => {
  const apart = pickFacts(ctx(withStat("longest_silence", { start: "2025-01-01" }))).find((f) => f.id === "busiest_day");
  assert.doesNotMatch(apart.line, /days without a word/);
  assert.equal(apart.visual, null);
  const together = pickFacts(ctx()).find((f) => f.id === "busiest_day");
  assert.deepEqual(together.visual, { kind: "gap", from: "2 August", to: "9 August", days: 6 });
});

test("the receipts never repeat a highlight, and say what counting cannot know", () => {
  const c = ctx();
  const facts = pickFacts(c);
  const r = receipts(c, facts);
  assert.equal(r.sections[0].items.length, facts.length);
  const also = r.sections[1].items.map((i) => i.label);
  assert.ok(also.includes("Affectionate messages") && also.includes("Pet name"));
  assert.match(r.sections[1].items.find((i) => i.label === "Affectionate messages").how, /counts words, not feelings/);
  assert.ok(r.limits.some((l) => /words, not feelings/.test(l)));
});

test("the poster: one idea, real bars, no names in the file name", () => {
  const p = posterContent(ctx());
  assert.deepEqual(p.titles.map((t) => t.text), ["hmm", "Rohan & Tara"]);
  assert.deepEqual(p.lines, ["Rohan sent 31 messages in a row.", "Tara said ‘I love you’ first."]);
  const run = demo.stats.find((s) => s.id === "longest_monologue").values;
  assert.deepEqual(p.monologue, { n: 31, lens: run.lens });
  assert.equal(p.lens, undefined);
  assert.doesNotMatch(p.fileName, /rohan|tara/i);
});

test("each bar is one real message, as long as it was, and any run fits the column", () => {
  const lens = demo.stats.find((s) => s.id === "longest_monologue").values.lens;
  const a = barLayout(lens, lens.length);
  assert.equal(a.bars.length, 31);
  const longest = lens.indexOf(Math.max(...lens)), shortest = lens.indexOf(Math.min(...lens));
  assert.ok(a.bars[longest].w > a.bars[shortest].w);
  assert.equal(Math.max(...a.bars.map((b) => b.w)), 560);
  for (const n of [12, 31, 108, 400]) { // 108 is a real-life run that broke the first prototype
    const l = barLayout(Array.from({ length: n }, (_, i) => (i * 7) % 50), n);
    assert.ok(l.gap >= 0, `gap for ${n}`);
    assert.ok(l.bars.at(-1).y + l.barH <= 1046 + 0.01, `last bar inside the column for ${n}`);
    assert.ok(l.bars.every((b, i) => i === 0 || b.y > l.bars[i - 1].y), `bars in order for ${n}`);
  }
  assert.equal(barLayout([0, 10], 2).bars[0].w, 36); // a photo in the run is a short stub
});

test("durations read like a person would say them", () => {
  assert.equal(duration(100), "1 min 40 s");
  assert.equal(duration(1375), "23 min");
  assert.equal(duration(45), "45 s");
  assert.equal(duration(120), "2 min");
});
